继续调查同一公开规则在本批输入上的表现。以前的判断能沿用到什么范围，有无值得正式检验的候选？
以下是独立的公开样例和待核验记录，样例程序是研究对象，尚未在当前完整求解器中执行。
{
  "instance": {
    "name": "quay-four",
    "capacity": 3,
    "depot": 0,
    "allowed_routes": 2,
    "use_integer_cost": true,
    "nodes": [
      {
        "id": 0,
        "x": 0,
        "y": 0,
        "demand": 0
      },
      {
        "id": 1,
        "x": 1,
        "y": 0,
        "demand": 2
      },
      {
        "id": 2,
        "x": 2,
        "y": 0,
        "demand": 2
      },
      {
        "id": 3,
        "x": 3,
        "y": 0,
        "demand": 1
      },
      {
        "id": 4,
        "x": 4,
        "y": 0,
        "demand": 1
      }
    ]
  },
  "program": "def propose(instance):\n    groups, load = [], 0\n    for n in sorted(instance['nodes'], key=lambda n: n['id']):\n        if n['id'] == instance['depot']:\n            continue\n        if not groups or load + n['demand'] > instance['capacity']:\n            groups.append([])\n            load = 0\n        groups[-1].append(n['id'])\n        load += n['demand']\n    return {'routes': groups}"
}
